98	/// The internal implementation of `compile` with a bit lower-level interface
99	/// that is also used by `trace`.
100	fn compile_impl<T: Output>(
101	    world: Tracked<dyn World + '_>,
102	    traced: Tracked<Traced>,
103	    sink: &mut Sink,
104	) -> SourceResult<T> {
105	    let library = world.library();
106	    match T::target() {
107	        Target::Paged => {}
108	        Target::Html => warn_or_error_for_html(&library.features, sink)?,
109	        Target::Bundle => warn_or_error_for_bundle(&library.features, sink)?,
110	    }
111	
112	    let base = StyleChain::new(&library.styles);
113	    let target = TargetElem::target.set(T::target()).wrap();
114	    let styles = base.chain(&target);
115	    let empty_introspector = EmptyIntrospector;
116	
117	    // Fetch the main source file once.
118	    let main = world.main();
119	    let main = world
120	        .source(main)
121	        .map_err(|err| hint_invalid_main_file(world, err, main))?;
122	
123	    // First evaluate the main source file into a module.
124	    let content = typst_eval::eval(
125	        world,
126	        library,
127	        traced,
128	        sink.track_mut(),
129	        Route::default().track(),
130	        &main,
131	    )?
132	    .content();
133	
134	    let mut history: ArrayVec<T, { MAX_ITERS - 1 }> = ArrayVec::new();
135	    let mut document: T;
136	
137	    // Relayout until all introspections stabilize.
138	    // If that doesn't happen within five attempts, we give up.
139	    loop {
140	        let _scope = TimingScope::new(ITER_NAMES[history.len()]);
141	        let introspector = history
142	            .last()
143	            .map(|doc| doc.introspector())
144	            .unwrap_or(&empty_introspector);
145	        let constraint = comemo::Constraint::new();
146	
147	        let mut subsink = Sink::new();
148	        let mut engine = Engine {
149	            library,
150	            world,
151	            introspector: Protected::new(introspector.track_with(&constraint)),
152	            traced,
153	            sink: subsink.track_mut(),
154	            route: Route::default(),
155	        };
156	
157	        document = T::create(&mut engine, &content, styles)?;
158	
159	        if timed!("check stabilized", constraint.validate(document.introspector())) {
160	            sink.extend_from_sink(subsink);
161	            break;
162	        }
163	
164	        if history.is_full() {
165	            let mut introspectors =
166	                [&empty_introspector as &dyn Introspector; MAX_ITERS + 1];
167	            for i in 1..MAX_ITERS {
168	                introspectors[i] = history[i - 1].introspector();
169	            }
170	            introspectors[MAX_ITERS] = document.introspector();
171	
172	            let warnings = typst_library::introspection::analyze(
173	                world,
174	                introspectors,
175	                subsink.introspections(),
176	            );
177	
178	            sink.extend_from_sink(subsink);
179	            for warning in warnings {
180	                sink.warn(warning);
181	            }
182	            break;
183	        }
184	
185	        history.push(document);
186	    }
187	
188	    // Promote delayed errors.
189	    let delayed = sink.delayed();
190	    if !delayed.is_empty() {
191	        return Err(delayed);
192	    }
193	
194	    Ok(document)
195	}
